function validateHttpResponse($headers=null) {
    if (!is_array($headers) or count($headers) &lt; 1) { return false; }
    switch(trim(strtolower($headers[0]))) {
        case &#039;http/1.0 100 ok&#039;:
        case &#039;http/1.0 200 ok&#039;:
        case &#039;http/1.1 100 ok&#039;:
