function unchunkHttpResponse($str=null) {
    if (!is_string($str) or strlen($str) &lt; 1) { return false; }
    $eol = &quot;\r\n&quot;;
    $add = strlen($eol);
    $tmp = $str;
    $str = &#039;&#039;;
    do {
        $tmp = ltrim($tmp);
        $pos = strpos($tmp, $eol);
        if ($pos === false) { return false; }
        $len = hexdec(substr($tmp,0,$pos));
